// ACCURACY TEST – compares the agent's fit rating with the candidate's own rating (my_fit)
// on jobs she labelled by hand. Reports:
// - exact agreement on the 4 fit bands (Strong / Possible / Weak / Red flag)
// - "apply or not" agreement: Strong + Possible = apply, Weak + Red flag = don't apply
//   with precision (of the jobs the agent says apply to, how many she agrees with)
//   and recall (of the jobs she wants, how many the agent found)
// - average score per band she chose, a confusion matrix and every disagreement
const BANDS = ["Strong", "Possible", "Weak", "Red flag"];
const norm = (s) => {
  const t = String(s || "").trim().toLowerCase();
  return BANDS.find((b) => b.toLowerCase() === t) || (t.startsWith("red") ? "Red flag" : "");
};
const rows = $input.all().map((i) => i.json).filter((r) => r.job_id && norm(r.my_fit) && norm(r.fit));
if (!rows.length) return [{ json: { message: "No labelled jobs yet. Fill the my_fit column (Strong / Possible / Weak / Red flag) for about 20 jobs, then run again." } }];

const apply = (b) => b === "Strong" || b === "Possible";
let exact = 0, tp = 0, fp = 0, fn = 0, tn = 0;
const matrix = Object.fromEntries(BANDS.map((h) => [h, Object.fromEntries(BANDS.map((a) => [a, 0]))]));
const disagreements = [];
const scoresByHuman = Object.fromEntries(BANDS.map((b) => [b, []]));
for (const r of rows) {
  const human = norm(r.my_fit), agent = norm(r.fit);
  matrix[human][agent]++;
  scoresByHuman[human].push(Number(r.match_score) || 0);
  if (human === agent) exact++;
  else disagreements.push(`${r.title} (${r.company}): you said ${human}, agent said ${agent} (${r.match_score})`);
  if (apply(agent) && apply(human)) tp++;
  else if (apply(agent) && !apply(human)) fp++;
  else if (!apply(agent) && apply(human)) fn++;
  else tn++;
}
const pct = (a, b) => (b ? Math.round((100 * a) / b) : null);
return [{ json: {
  labelled_jobs: rows.length,
  exact_band_agreement_pct: pct(exact, rows.length),
  apply_decision_agreement_pct: pct(tp + tn, rows.length),
  apply_precision_pct: pct(tp, tp + fp),
  apply_recall_pct: pct(tp, tp + fn),
  avg_agent_score_by_your_band: Object.fromEntries(BANDS.filter((b) => scoresByHuman[b].length)
    .map((b) => [b, Math.round(scoresByHuman[b].reduce((s, x) => s + x, 0) / scoresByHuman[b].length)])),
  confusion_matrix_rows_you_cols_agent: matrix,
  disagreements
} }];
